        else:
            i+=1
    if a_path is None or b_path is None:
        sys.stderr.write(HELP_TEXTS.get('subtract','')+"\n")
        sys.exit(1)
    recs_a, hdrs = read_bed_records(a_path)
    recs_b,_ = read_bed_records(b_path)
    from collections import defaultdict
    b_by_chrom=defaultdict(list)
    for rec in recs_b:
        b_by_chrom[rec[0]].append(rec)
    out=sys.stdout
    if header:
        for h in hdrs:
            out.write(h+"\n")
    for rec_a in recs_a:
        chrom_a,start_a,end_a,extra_a,line_a=rec_a
        overlapping=[]
        for rec_b in b_by_chrom.get(chrom_a, []):
            if s_flag and strand_of(rec_a)!=strand_of(rec_b):
                continue
            if S_flag and strand_of(rec_a)==strand_of(rec_b):
                continue
            ol=overlap_len(start_a,end_a,rec_b[1],rec_b[2])
            if ol==0:
                continue
            fa=ol/(end_a-start_a) if end_a>start_a else 0
            fb=ol/(rec_b[2]-rec_b[1]) if rec_b[2]>rec_b[1] else 0
            ok=True
            if r_flag:
                if f_thresh is not None and not (fa>=f_thresh and fb>=f_thresh):
                    ok=False
                if F_thresh is not None and not (fa>=F_thresh and fb>=F_thresh):
                    ok=False
            else:
                if e_flag:
                    cond=False
                    if f_thresh is not None and fa>=f_thresh:
                        cond=True
                    if F_thresh is not None and fb>=F_thresh:
                        cond=True
                    if f_thresh is None and F_thresh is None:
                        cond=True
                    ok=cond
                else:
                    if f_thresh is not None and fa<f_thresh:
                        ok=False
                    if F_thresh is not None and fb<F_thresh:
                        ok=False
            if ok:
                overlapping.append(rec_b)
        if A_flag:
            if overlapping:
                continue
            else:
                out.write(line_a+"\n")
        else:
            if not overlapping:
                out.write(line_a+"\n")
            else:
                segs=[]
                for rb in overlapping:
                    s=max(start_a, rb[1]); e=min(end_a, rb[2])
                    if s<e:
                        segs.append((s,e))
                segs.sort()
                merged_seg=[]
                for s,e in segs:
                    if not merged_seg:
                        merged_seg.append([s,e])
                    else:
                        last=merged_seg[-1]
                        if s<=last[1]:
                            if e>last[1]:
                                last[1]=e
                        else:
                            merged_seg.append([s,e])
                cur=start_a
                for s,e in merged_seg:
                    if cur < s:
                        fields=line_a.split('\t')
                        if len(fields)>=3:
                            fields[1]=str(cur); fields[2]=str(s)
                            out.write("\t".join(fields)+"\n")
                        else:
                            out.write(f"{chrom_a}\t{cur}\t{s}\n")
                    cur=max(cur,e)
                if cur < end_a:
                    fields=line_a.split('\t')
                    if len(fields)>=3:
                        fields[1]=str(cur); fields[2]=str(end_a)
                        out.write("\t".join(fields)+"\n")
                    else:
                        out.write(f"{chrom_a}\t{cur}\t{end_a}\n")

