            input_path=args[i+1]; i+=2
        elif arg.startswith('-i') and len(arg)>2:
            input_path=arg[2:]; i+=1
        elif arg=='-g' and i+1 < len(args):
            genome_path=args[i+1]; i+=2
        elif arg.startswith('-g') and len(arg)>2:
            genome_path=arg[2:]; i+=1
        elif arg=='-bg':
            bg=True; i+=1
        elif arg=='-bga':
            bga=True; i+=1
        elif arg=='-d':
            d_flag=True; i+=1
        elif arg=='-dz':
            dz=True; i+=1
        elif arg=='-scale' and i+1 < len(args):
            try:
                scale=float(args[i+1])
            except:
                pass
            i+=2
        else:
            i+=1
    if genome_path is None:
        sys.stderr.write(HELP_TEXTS.get('genomecov','')+"\n")
        sys.exit(1)
    try:
        chrom_sizes, chrom_order = parse_genome_file(genome_path)
    except:
        sys.stderr.write(f"Error: Unable to open file {genome_path}. Exiting.\n")
        sys.exit(1)
    recs,_=read_bed_records(input_path)
    from collections import defaultdict
    by_chrom=defaultdict(list)
    for rec in recs:
        by_chrom[rec[0]].append(rec)
    out=sys.stdout
    if bg or bga:
        for chrom in chrom_order:
            size=chrom_sizes.get(chrom,0)
            intervals=by_chrom.get(chrom, [])
            if not intervals:
                if bga:
                    out.write(f"{chrom}\t0\t{size}\t0\n")
                continue
            events=defaultdict(int)
            for rec in intervals:
                s=max(0,min(rec[1],size)); e=max(0,min(rec[2],size))
                if s>=e:
                    continue
                events[s]+=1; events[e]-=1
            sorted_pos=sorted(events.keys())
            cur_cov=0
            prev=None
            for pos in sorted_pos:
                if prev is not None and prev < pos:
                    if cur_cov>0 or bga:
                        sc=cur_cov*scale
                        if sc==int(sc):
                            sc=int(sc)
                        out.write(f"{chrom}\t{prev}\t{pos}\t{sc}\n")
                cur_cov+=events[pos]
                prev=pos
            if bga and prev is not None and prev < size:
                out.write(f"{chrom}\t{prev}\t{size}\t0\n")
    elif d_flag:
        for chrom in chrom_order:
            size=chrom_sizes.get(chrom,0)
            intervals=by_chrom.get(chrom, [])
            events=defaultdict(int)
            for rec in intervals:
                s=max(0,min(rec[1],size)); e=max(0,min(rec[2],size))
                if s>=e:
                    continue
                events[s]+=1; events[e]-=1
            sorted_pos=sorted(events.keys())
            cur_cov=0
            idx=0
            for pos in range(size):
                while idx < len(sorted_pos) and sorted_pos[idx] <= pos:
                    cur_cov+=events[sorted_pos[idx]]
                    idx+=1
                out.write(f"{chrom}\t{pos+1}\t{cur_cov}\n")
    elif dz:
        for chrom in chrom_order:
            size=chrom_sizes.get(chrom,0)
            intervals=by_chrom.get(chrom, [])
            events=defaultdict(int)
            for rec in intervals:
                s=max(0,min(rec[1],size)); e=max(0,min(rec[2],size))
                if s>=e:
                    continue
                events[s]+=1; events[e]-=1
            sorted_pos=sorted(events.keys())
            cur_cov=0
            idx=0
            for pos in range(size):
                while idx < len(sorted_pos) and sorted_pos[idx] <= pos:
                    cur_cov+=events[sorted_pos[idx]]
                    idx+=1
                if cur_cov>0:
                    out.write(f"{chrom}\t{pos}\t{cur_cov}\n")
    else:
        from collections import Counter
        overall=Counter()
        total_size=0
        for chrom in chrom_order:
            size=chrom_sizes.get(chrom,0)
            total_size+=size
            intervals=by_chrom.get(chrom, [])
            events=defaultdict(int)
            for rec in intervals:
                s=max(0,min(rec[1],size)); e=max(0,min(rec[2],size))
                if s>=e:
                    continue
                events[s]+=1; events[e]-=1
            sorted_pos=sorted(events.keys())
            cur_cov=0
            prev=0
            chrom_counter=Counter()
            for pos in sorted_pos:
                if pos>prev:
                    length=pos-prev
                    chrom_counter[cur_cov]+=length
                    overall[cur_cov]+=length
                cur_cov+=events[pos]
                prev=pos
            if prev < size:
                length=size-prev
                chrom_counter[cur_cov]+=length
                overall[cur_cov]+=length
            for depth in sorted(chrom_counter.keys()):
                bases=chrom_counter[depth]
                frac=bases/size if size>0 else 0
                out.write(f"{chrom}\t{depth}\t{bases}\t{size}\t{frac:.7f}\n")
        for depth in sorted(overall.keys()):
            bases=overall[depth]
            frac=bases/total_size if total_size>0 else 0
            out.write(f"genome\t{depth}\t{bases}\t{total_size}\t{frac:.7f}\n")

def tool_jaccard(args):
    if '-h' in args or '--help' in args:
        sys.stderr.write(HELP_TEXTS.get('jaccard','')+"\n")
        sys.exit(1)
    a_path=None; b_path=None
    i=0
    while i < len(args):
        arg=args[i]
        if arg=='-a' and i+1 < len(args):
            a_path=args[i+1]; i+=2
        elif arg.startswith('-a') and len(arg)>2:
            a_path=arg[2:]; i+=1
        elif arg=='-b' and i+1 < len(args):
            b_path=args[i+1]; i+=2
        elif arg.startswith('-b') and len(arg)>2:
            b_path=arg[2:]; i+=1
        else:
            i+=1
    if a_path is None or b_path is None:
        sys.stderr.write(HELP_TEXTS.get('jaccard','')+"\n")
        sys.exit(1)
    recs_a,_=read_bed_records(a_path)
    recs_b,_=read_bed_records(b_path)
    from collections import defaultdict
    def merge_intervals(recs):
        by_chrom=defaultdict(list)
        for rec in recs:
            by_chrom[rec[0]].append((rec[1],rec[2]))
        merged_by={}
        total=0
        for chrom, intervals in by_chrom.items():
            intervals.sort()
            merged=[]
            for s,e in intervals:
                if not merged:
                    merged.append([s,e])
                else:
                    last=merged[-1]
                    if s <= last[1]:
                        if e>last[1]:
                            last[1]=e
                    else:
                        merged.append([s,e])
            merged_by[chrom]=merged
            for s,e in merged:
                total+=e-s
        return merged_by,total
    merged_a,total_a=merge_intervals(recs_a)
    merged_b,total_b=merge_intervals(recs_b)
    inter=0
    n=0
    all_chroms=set(merged_a.keys())|set(merged_b.keys())
    for chrom in all_chroms:
        a_int=merged_a.get(chrom, [])
        b_int=merged_b.get(chrom, [])
        i=j=0
        a_int.sort(); b_int.sort()
        while i < len(a_int) and j < len(b_int):
            a_s,a_e=a_int[i]; b_s,b_e=b_int[j]
            ov_s=max(a_s,b_s); ov_e=min(a_e,b_e)
            if ov_s < ov_e:
                inter+=ov_e-ov_s; n+=1
            if a_e < b_e:
                i+=1
            else:
                j+=1
    union=total_a+total_b-inter
    jacc=inter/union if union>0 else 0
    out=sys.stdout
    out.write("intersection\tunion\tjaccard\tn_intersections\n")
    out.write(f"{inter}\t{union}\t{jacc}\t{n}\n")

