            src_name=extra[0] if extra else ""
            length=end-start
            windows=[]
            if w_val is not None:
                step=s_val if s_val is not None else w_val
                pos=start
                while pos < end:
                    win_end=pos+w_val
                    if win_end>end:
                        win_end=end
                    windows.append((pos,win_end))
                    pos+=step
            else:
                for idx in range(n_val):
                    ws=start+int(idx*length/n_val)
                    we=start+int((idx+1)*length/n_val)
                    if idx==n_val-1:
                        we=end
                    windows.append((ws,we))
            total=len(windows)
            for idx,(ws,we) in enumerate(windows):
                win_num=idx+1
                if reverse:
                    win_num=total-idx
                if id_opt is None:
                    out.write(f"{chrom}\t{ws}\t{we}\n")
                elif id_opt=='winnum':
                    out.write(f"{chrom}\t{ws}\t{we}\t{win_num}\n")
                elif id_opt=='src':
                    out.write(f"{chrom}\t{ws}\t{we}\t{src_name}\n")
                elif id_opt=='srcwinnum':
                    if src_name:
                        out.write(f"{chrom}\t{ws}\t{we}\t{src_name}_{win_num}\n")
                    else:
