def tool_groupby(args):
    if '-h' in args or '--help' in args:
        sys.stderr.write(HELP_TEXTS.get('groupby','')+"\n")
        sys.exit(1)
    input_path=None
    g_cols=None
    c_cols=None
    o_ops=None
    full=False
    inheader=False
    outheader=False
    ignorecase=False
    prec=5
    delim=","
    i=0
    while i < len(args):
        arg=args[i]
        if arg=='-i' and i+1 < len(args):
            input_path=args[i+1]; i+=2
        elif arg.startswith('-i') and len(arg)>2 and arg not in ('-inheader',):
            input_path=arg[2:]; i+=1
        elif arg in ('-g','-grp'):
            if i+1 < len(args):
                g_cols=args[i+1]; i+=2
            else:
                i+=1
        elif arg.startswith('-g'):
            if len(arg)>2:
                g_cols=arg[2:]; i+=1
            else:
                i+=1
        elif arg.startswith('-grp'):
            if i+1 < len(args):
                g_cols=args[i+1]; i+=2
            else:
                i+=1
        elif arg in ('-c','-opCols'):
            if i+1 < len(args):
                c_cols=args[i+1]; i+=2
            else:
                i+=1
        elif arg.startswith('-c'):
            if len(arg)>2:
                c_cols=arg[2:]; i+=1
            else:
                i+=1
        elif arg.startswith('-opCols'):
            if '=' in arg:
                c_cols=arg.split('=',1)[1]
            elif i+1 < len(args):
                c_cols=args[i+1]; i+=2
            else:
                i+=1
        elif arg in ('-o','-ops'):
            if i+1 < len(args):
                o_ops=args[i+1]; i+=2
            else:
                i+=1
        elif arg.startswith('-o'):
            if len(arg)>2 and not arg.startswith('-op'):
                o_ops=arg[2:]; i+=1
            else:
                i+=1
        elif arg.startswith('-ops'):
            if '=' in arg:
                o_ops=arg.split('=',1)[1]
            elif i+1 < len(args):
                o_ops=args[i+1]; i+=2
            else:
                i+=1
        elif arg=='-full':
            full=True; i+=1
        elif arg=='-inheader':
            inheader=True; i+=1
        elif arg=='-outheader':
            outheader=True; i+=1
        elif arg=='-header':
            inheader=True; outheader=True; i+=1
        elif arg=='-ignorecase':
            ignorecase=True; i+=1
        elif arg=='-prec' and i+1 < len(args):
            try:
                prec=int(args[i+1])
            except:
                pass
            i+=2
        elif arg.startswith('-prec'):
            if '=' in arg:
                try:
                    prec=int(arg.split('=',1)[1])
                except:
                    pass
            i+=1
        elif arg=='-delim' and i+1 < len(args):
            delim=args[i+1]; i+=2
        elif arg.startswith('-delim'):
            if '=' in arg:
                delim=arg.split('=',1)[1]
            elif len(arg)>6:
                delim=arg[6:]
            i+=1
        else:
            i+=1
    if c_cols is None:
        sys.stderr.write(HELP_TEXTS.get('groupby','')+"\n")
        sys.exit(1)
    if g_cols is None:
        g_cols="1,2,3"
    def parse_cols(s):
        res=[]
        for part in s.split(','):
            part=part.strip()
            if not part:
                continue
            try:
                res.append(int(part))
            except:
                pass
        return res
    g_list=parse_cols(g_cols)
    c_list=parse_cols(c_cols)
    o_list=[op.strip() for op in o_ops.split(',')] if o_ops else ['sum']
    if len(c_list)==1 and len(o_list)>1:
        ext_c=c_list*len(o_list); ext_o=o_list
    elif len(o_list)==1 and len(c_list)>1:
        ext_c=c_list; ext_o=o_list*len(c_list)
    else:
        ext_c=c_list; ext_o=o_list
        if len(ext_c)!=len(ext_o):
            max_len=max(len(ext_c), len(ext_o))
            if len(ext_c)<max_len:
                ext_c=(ext_c*max_len)[:max_len]
            if len(ext_o)<max_len:
                ext_o=(ext_o*max_len)[:max_len]
    fh=open_input(input_path) if input_path else sys.stdin
    lines=[]
    headers=[]
    first=True
    for raw in fh:
        line=raw.rstrip('\n')
        if not line:
            continue
        if first and inheader:
            headers.append(line)
            first=False
            continue
        first=False
        fields=line.split('\t')
        lines.append((fields,line))
    if fh is not sys.stdin:
        fh.close()
    def group_key(fields):
        key=[]
        for col in g_list:
            idx=col-1
            if idx < len(fields):
                v=fields[idx]
                if ignorecase:
                    v=v.lower()
                key.append(v)
            else:
                key.append("")
        return tuple(key)
    out=sys.stdout
    if outheader:
        if headers:
            h_fields=headers[0].split('\t')
            out_fields=[]
            for col in g_list:
                idx=col-1
                if idx < len(h_fields):
                    out_fields.append(h_fields[idx])
                else:
                    out_fields.append(f"col_{col}")
            for col,op in zip(ext_c, ext_o):
                idx=col-1
                if idx < len(h_fields):
                    cn=h_fields[idx]
                else:
                    cn=f"col_{col}"
                out_fields.append(f"{cn}_{op}")
            out.write("\t".join(out_fields)+"\n")
        else:
            out_fields=[]
            for col in g_list:
                out_fields.append(f"col_{col}")
            for col,op in zip(ext_c, ext_o):
                out_fields.append(f"col_{col}_{op}")
            out.write("\t".join(out_fields)+"\n")
    cur_key=None
    cur_group=[]
    def flush():
        nonlocal cur_group
        if not cur_group:
            return
        first_fields=cur_group[0][0]
        if full:
            out_fields=first_fields[:]
        else:
            out_fields=[]
            for col in g_list:
                idx=col-1
                if idx < len(first_fields):
                    out_fields.append(first_fields[idx])
                else:
                    out_fields.append("")
        for col_idx, op in zip(ext_c, ext_o):
            vals=[]
            for fields,_ in cur_group:
                idx=col_idx-1
                if idx < len(fields):
                    vals.append(fields[idx])
                else:
                    vals.append("")
            num_vals=[]
            for v in vals:
                try:
                    num_vals.append(float(v))
                except:
                    pass
            op_low=op.lower()
            res=""
            if op_low=='sum':
                s=sum(num_vals) if num_vals else 0
                res=str(int(round(s))) if abs(s-round(s))<1e-9 else f"{s:.{prec}f}"
            elif op_low=='count':
                res=str(len(vals))
            elif op_low=='count_distinct':
                res=str(len(set(vals)))
            elif op_low=='min':
                if num_vals:
                    m=min(num_vals)
                    res=str(int(m) if float(m).is_integer() else m)
                else:
                    res=min(vals) if vals else ""
            elif op_low=='max':
                if num_vals:
                    m=max(num_vals)
                    res=str(int(m) if float(m).is_integer() else m)
                else:
                    res=max(vals) if vals else ""
            elif op_low=='mean':
                if num_vals:
                    m=sum(num_vals)/len(num_vals)
                    res=str(int(round(m))) if abs(m-round(m))<1e-9 else f"{m:.{prec}f}"
                else:
                    res=""
            elif op_low=='median':
                if num_vals:
                    import statistics
                    med=statistics.median(num_vals)
                    res=str(int(med) if float(med).is_integer() else f"{med:.{prec}f}")
                else:
                    res=""
            elif op_low=='mode':
                from collections import Counter
                cnt=Counter(vals)
                res=cnt.most_common(1)[0][0] if cnt else ""
            elif op_low=='antimode':
                from collections import Counter
                cnt=Counter(vals)
                res=cnt.most_common()[-1][0] if cnt else ""
            elif op_low=='stdev':
                if len(num_vals)>=2:
                    import statistics
                    sd=statistics.pstdev(num_vals)
                    res=f"{sd:.{prec}f}"
                else:
                    res="0"
            elif op_low=='sstdev':
                if len(num_vals)>=2:
                    import statistics
                    try:
                        sd=statistics.stdev(num_vals)
                    except:
                        sd=0
                    res=f"{sd:.{prec}f}"
                else:
                    res="0"
            elif op_low=='collapse':
                res=delim.join(vals)
            elif op_low=='distinct':
                seen=set(); uniq=[]
                for v in vals:
                    if v not in seen:
                        seen.add(v); uniq.append(v)
                res=delim.join(uniq)
            elif op_low=='concat':
                res="".join(vals)
            elif op_low=='first':
                res=vals[0] if vals else ""
            elif op_low=='last':
                res=vals[-1] if vals else ""
            else:
                res=delim.join(vals)
            out_fields.append(res)
        out.write("\t".join(out_fields)+"\n")
        cur_group=[]
    for fields,line in lines:
        key=group_key(fields)
        if cur_key is None:
            cur_key=key
            cur_group.append((fields,line))
        elif key==cur_key:
            cur_group.append((fields,line))
        else:
            flush()
            cur_key=key
            cur_group.append((fields,line))
    flush()

