        ops=None
    for chrom,start,end,group_recs,_ in merged:
        if cols is None:
            out.write(f"{chrom}\t{start}\t{end}\n")
        else:
            if ops is None:
                ops=['sum']*len(cols)
            if len(cols)==1 and len(ops)>1:
                ext_cols=cols*len(ops)
                ext_ops=ops
            elif len(ops)==1 and len(cols)>1:
                ext_cols=cols
                ext_ops=ops*len(cols)
            else:
                ext_cols=cols
                ext_ops=ops
                if len(ext_cols)!=len(ext_ops):
                    if len(ext_ops)<len(ext_cols):
                        ext_ops=(ext_ops*len(ext_cols))[:len(ext_cols)]
                    else:
                        ext_cols=(ext_cols*len(ext_ops))[:len(ext_ops)]
            res_fields=[]
            for col_idx, op in zip(ext_cols, ext_ops):
                vals=[get_col(r, col_idx) for r in group_recs]
                num_vals=[]
                for v in vals:
                    try:
                        num_vals.append(float(v))
                    except:
                        pass
                op_low=op.lower()
                res=""
                if op_low=='sum':
                    s=sum(num_vals) if num_vals else 0
                    if abs(s-round(s))<1e-9:
                        res=str(int(round(s)))
                    else:
                        res=f"{s:.{prec}f}"
                elif op_low=='min':
                    if num_vals:
                        m=min(num_vals)
                        res=str(int(m) if float(m).is_integer() else m)
                    else:
                        res=""
                elif op_low=='max':
                    if num_vals:
                        m=max(num_vals)
                        res=str(int(m) if float(m).is_integer() else m)
                    else:
                        res=""
                elif op_low=='mean':
                    if num_vals:
                        m=sum(num_vals)/len(num_vals)
                        if abs(m-round(m))<1e-9:
                            res=str(int(round(m)))
                        else:
                            res=f"{m:.{prec}f}"
                    else:
                        res=""
                elif op_low=='median':
                    if num_vals:
                        import statistics
                        med=statistics.median(num_vals)
                        res=str(int(med) if float(med).is_integer() else f"{med:.{prec}f}")
                    else:
                        res=""
                elif op_low=='collapse':
                    res=delim.join(vals)
                elif op_low=='distinct':
                    seen=set(); uniq=[]
                    for v in vals:
                        if v not in seen:
                            seen.add(v); uniq.append(v)
                    res=delim.join(uniq)
                elif op_low=='count':
                    res=str(len(vals))
                elif op_low=='count_distinct':
                    res=str(len(set(vals)))
                elif op_low=='first':
                    res=vals[0] if vals else ""
                elif op_low=='last':
                    res=vals[-1] if vals else ""
                elif op_low in ('mode','antimode'):
                    from collections import Counter
                    cnt=Counter(vals)
                    if cnt:
                        if op_low=='mode':
                            res=cnt.most_common(1)[0][0]
                        else:
                            res=cnt.most_common()[-1][0]
                    else:
                        res=""
                elif op_low in ('stdev','sstdev'):
                    if len(num_vals)>=2:
                        import statistics
                        if op_low=='stdev':
                            sd=statistics.pstdev(num_vals)
                        else:
                            sd=statistics.stdev(num_vals)
                        res=f"{sd:.{prec}f}"
                    else:
                        res="0"
                else:
                    res=delim.join(vals)
                res_fields.append(res)
            out.write(f"{chrom}\t{start}\t{end}\t" + "\t".join(res_fields)+"\n")

