        help_txt=HELP_TEXTS.get('complement','')
        sys.stderr.write(help_txt+"\n\n\n***** ERROR: no -g genome file provided. *****\n\n")
        sys.exit(1)
    try:
        chrom_sizes, chrom_order = parse_genome_file(genome_path)
    except SystemExit:
        raise
    recs,_=read_bed_records(input_path)
    from collections import defaultdict
    by_chrom=defaultdict(list)
    for rec in recs:
        by_chrom[rec[0]].append((rec[1],rec[2]))
    out=sys.stdout
    chroms_to_process = chrom_order
    if L_flag:
        chroms_to_process = [c for c in chrom_order if c in by_chrom]
    for chrom in chroms_to_process:
        size=chrom_sizes.get(chrom)
        if size is None:
            continue
        intervals=sorted(by_chrom.get(chrom, []))
        merged=[]
        for s,e in intervals:
            if not merged:
                merged.append([s,e])
            else:
                last=merged[-1]
                if s <= last[1]:
                    if e>last[1]:
                        last[1]=e
                else:
                    merged.append([s,e])
        prev_end=0
        for s,e in merged:
            s=max(0,s); e=min(size,e)
            if s>prev_end:
                out.write(f"{chrom}\t{prev_end}\t{s}\n")
            if e>prev_end:
                prev_end=e
        if prev_end < size:
            out.write(f"{chrom}\t{prev_end}\t{size}\n")

