                    if F_thresh is not None and fb>=F_thresh:
                        cond=True
                    if f_thresh is None and F_thresh is None:
                        cond=True
                    ok=cond
                else:
                    if f_thresh is not None and fa<f_thresh:
                        ok=False
                    if F_thresh is not None and fb<F_thresh:
                        ok=False
            if ok:
                overlapping.append(rec_b)
        if A_flag:
            if overlapping:
                continue
            else:
                out.write(line_a+"\n")
        else:
            if not overlapping:
                out.write(line_a+"\n")
            else:
                segs=[]
                for rb in overlapping:
                    s=max(start_a, rb[1]); e=min(end_a, rb[2])
                    if s<e:
                        segs.append((s,e))
                segs.sort()
                merged_seg=[]
                for s,e in segs:
                    if not merged_seg:
                        merged_seg.append([s,e])
                    else:
                        last=merged_seg[-1]
                        if s<=last[1]:
                            if e>last[1]:
                                last[1]=e
                        else:
                            merged_seg.append([s,e])
                cur=start_a
                for s,e in merged_seg:
                    if cur < s:
                        fields=line_a.split('\t')
                        if len(fields)>=3:
                            fields[1]=str(cur); fields[2]=str(s)
                            out.write("\t".join(fields)+"\n")
                        else:
                            out.write(f"{chrom_a}\t{cur}\t{s}\n")
                    cur=max(cur,e)
                if cur < end_a:
                    fields=line_a.split('\t')
                    if len(fields)>=3:
                        fields[1]=str(cur); fields[2]=str(end_a)
                        out.write("\t".join(fields)+"\n")
                    else:
                        out.write(f"{chrom_a}\t{cur}\t{end_a}\n")

