        best=None; best_dist=None
        for b_rec in blist:
            if s_flag and strand_of(a_rec)!=strand_of(b_rec):
                continue
            if S_flag and strand_of(a_rec)==strand_of(b_rec):
                continue
            ol=overlap_len(start_a,end_a,b_rec[1],b_rec[2])
