            # upstream negative
            if best[2] <= start_a:
                signed=-best_dist
        if d_flag:
            out.write(line_a+"\t"+best[4]+f"\t{best_dist}\n")
        elif D_opt:
            out.write(line_a+"\t"+best[4]+f"\t{signed}\n")
