            except:
                s_val=None
            # need to check if next is actually id_opt? For makewindows -s is step, -i is id
            # So if next arg is not number, it's not step? Let's check: -s step is numeric, -i is separate. So we parse numeric.
            # We'll attempt to detect if next token is numeric
            nxt=args[i+1] if i+1 < len(args) else None
            if nxt and re.match(r'^\d+$', nxt):
                try:
                    s_val=int(nxt)
