                    s_val=None
                i+=2
            else:
                i+=1
        elif arg.startswith('-s') and len(arg)>2:
            try:
                s_val=int(arg[2:])
            except:
                pass
            i+=1
        elif arg=='-n' and i+1 < len(args):
