                n_val=int(arg[2:])
            except:
                pass
            i+=1
        elif arg=='-reverse':
            reverse=True; i+=1
        elif arg=='-i' and i+1 < len(args):
            id_opt=args[i+1]; i+=2
        elif arg.startswith('-i') and len(arg)>2:
            id_opt=arg[2:]; i+=1
        else:
            i+=1
    # Handle -s parsing more robustly: look for any arg that is purely number after -w?
    # Re-parse for -s if not found but args contain -s num
    if s_val is None:
        # search
        for idx in range(len(args)-1):
            if args[idx]=='-s':
                try:
                    s_val=int(args[idx+1])
                except:
                    pass
    if genome_path is None and bed_path is None:
        sys.stderr.write("\n*****\n*****ERROR: Need -g (genome file) or -b (BED file) for interval source. \n*****\n\n")
        if w_val is None and n_val is None:
            sys.stderr.write("\n*****\n*****ERROR: Need -w (window size) or -n (number of windows). \n*****\n\n")
        sys.stderr.write(HELP_TEXTS.get('makewindows','')+"\n")
        sys.exit(1)
    if w_val is None and n_val is None:
        sys.stderr.write("\n*****\n*****ERROR: Need -w (window size) or -n (number of windows). \n*****\n\n")
        sys.stderr.write("\n*****\n*****ERROR: The step (-s) option must be greater than zero. \n*****\n\n")
        sys.stderr.write(HELP_TEXTS.get('makewindows','')+"\n")
