        for chrom in chrom_order:
            size=chrom_sizes[chrom]
            windows=[]
            if w_val is not None:
                step=s_val if s_val is not None else w_val
                pos=0
                while pos < size:
                    end=pos+w_val
                    if end>size:
                        end=size
                    windows.append((pos,end))
                    pos+=step
            else:
                for idx in range(n_val):
                    ws=int(idx*size/n_val)
                    we=int((idx+1)*size/n_val)
                    if idx==n_val-1:
                        we=size
                    windows.append((ws,we))
            total=len(windows)
            for idx,(s,e) in enumerate(windows):
                win_num=idx+1
