                    pass
            op_low=op.lower()
            res=""
            if op_low=='sum':
                s=sum(num_vals) if num_vals else 0
                res=str(int(round(s))) if abs(s-round(s))<1e-9 else f"{s:.{prec}f}"
            elif op_low=='count':
                res=str(len(vals))
            elif op_low=='count_distinct':
                res=str(len(set(vals)))
            elif op_low=='min':
                if num_vals:
                    m=min(num_vals)
                    res=str(int(m) if float(m).is_integer() else m)
                else:
                    res=min(vals) if vals else ""
            elif op_low=='max':
                if num_vals:
                    m=max(num_vals)
                    res=str(int(m) if float(m).is_integer() else m)
                else:
                    res=max(vals) if vals else ""
            elif op_low=='mean':
                if num_vals:
                    m=sum(num_vals)/len(num_vals)
                    res=str(int(round(m))) if abs(m-round(m))<1e-9 else f"{m:.{prec}f}"
                else:
                    res=""
            elif op_low=='median':
                if num_vals:
                    import statistics
                    med=statistics.median(num_vals)
                    res=str(int(med) if float(med).is_integer() else f"{med:.{prec}f}")
                else:
                    res=""
            elif op_low=='mode':
                from collections import Counter
                cnt=Counter(vals)
                res=cnt.most_common(1)[0][0] if cnt else ""
            elif op_low=='antimode':
                from collections import Counter
                cnt=Counter(vals)
                res=cnt.most_common()[-1][0] if cnt else ""
            elif op_low=='stdev':
                if len(num_vals)>=2:
                    import statistics
                    sd=statistics.pstdev(num_vals)
                    res=f"{sd:.{prec}f}"
                else:
                    res="0"
            elif op_low=='sstdev':
                if len(num_vals)>=2:
                    import statistics
                    try:
                        sd=statistics.stdev(num_vals)
                    except:
                        sd=0
                    res=f"{sd:.{prec}f}"
                else:
                    res="0"
            elif op_low=='collapse':
                res=delim.join(vals)
            elif op_low=='distinct':
                seen=set(); uniq=[]
                for v in vals:
